package com.rescuefarm.ui.checkout;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import com.rescuefarm.R;import com.rescuefarm.domain.model.Order;
public class OrderConfirmationFragment extends Fragment{private OrderViewModel vm;private TextView output;private EditText code,phone;@Nullable public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){return i.inflate(R.layout.fragment_order_confirmation,p,false);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){output=v.findViewById(R.id.orderConfirmationText);code=v.findViewById(R.id.trackingOrderCode);phone=v.findViewById(R.id.trackingPhone);Bundle a=getArguments();if(a!=null){code.setText(a.getString("orderCode",""));phone.setText(a.getString("phone",""));output.setText(getString(R.string.order_created_format,a.getString("orderCode",""),a.getString("status","PENDING")));}vm=new ViewModelProvider(this,new OrderViewModelFactory(requireContext())).get(OrderViewModel.class);vm.getState().observe(getViewLifecycleOwner(),x->{if(x.getStatus()==CheckoutState.Status.SUCCESS)render(x.getOrder());else if(x.getStatus()==CheckoutState.Status.ERROR)Toast.makeText(requireContext(),x.getMessage(),Toast.LENGTH_LONG).show();});v.findViewById(R.id.trackOrderButton).setOnClickListener(x->vm.findGuest(code.getText().toString(),phone.getText().toString()));}private void render(Order o){output.setText(getString(R.string.order_tracking_format,o.getOrderCode(),o.getStatus().name(),o.getPaymentStatus().name(),o.getTotalAmount()));}}
